package org.dextur.reputation.storage;
import java.time.*;
import java.util.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.domain.recovery.*;
import org.dextur.reputation.domain.recovery.RecoveryData.*;
import org.dextur.reputation.domain.protection.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.dextur.reputation.storage.RecoveryFixtures.*;
class RecoveryEnginePolicyTest {
 @org.junit.jupiter.api.io.TempDir java.nio.file.Path directory;
 ReputationSnapshot profile(long score){return new ReputationSnapshot(PLAYER,"global",score,0,score,"OFFENDER",0,NOW.minusSeconds(1000000),NOW);}
 Request facts(long play,Instant first){return new Request(UUID.randomUUID(),PLAYER,"global",Command.START,NOW,new Facts(true,play,first),ZERO,0,0,false,ZERO,"",0,"","PLAYER","",Set.of());}
 @Test void exactThresholdPlaytimeAndAgeBoundaries(){var rules=rules(RecoveryRules.Type.ACTIVE_PLAYTIME);assertEquals(RecoverySnapshot.Status.ACTIVE,RecoveryEngine.evaluate(null,profile(-100),null,rules,facts(108000,NOW.minusSeconds(604800))).snapshot().status());assertThrows(IllegalStateException.class,()->RecoveryEngine.evaluate(null,profile(-99),null,rules,facts(108000,NOW.minusSeconds(604800))));assertThrows(IllegalStateException.class,()->RecoveryEngine.evaluate(null,profile(-100),null,rules,facts(107999,NOW.minusSeconds(604800))));assertThrows(IllegalStateException.class,()->RecoveryEngine.evaluate(null,profile(-100),null,rules,facts(108000,NOW.minusSeconds(604799))));}
 @Test void activeEnrollmentSurvivesReputationImprovement(){var rules=rules(RecoveryRules.Type.ACTIVE_PLAYTIME);var start=RecoveryEngine.evaluate(null,profile(-100),null,rules,facts(108000,NOW.minusSeconds(604800)));var changed=RecoveryEngine.evaluate(start.state(),profile(-99),null,rules,request(Command.READ,NOW.plusSeconds(1)));assertEquals(RecoverySnapshot.Status.ACTIVE,changed.snapshot().status());assertEquals(start.state().current().id(),changed.state().current().id());}
 @Test void invalidExternalProgressAndUnavailableNeverAutoComplete(){var rules=rules(RecoveryRules.Type.EXTERNAL);var initial=RecoveryEngine.evaluate(null,profile(-100),null,rules,request(Command.START,NOW));assertEquals(RecoverySnapshot.Status.PAUSED,initial.snapshot().status());assertFalse(initial.snapshot().objectives().getFirst().available());assertTrue(initial.state().rewards().isEmpty());var resume=request(UUID.randomUUID(),Command.RESUME,NOW,0,0,ZERO,false,ZERO,"",0,Set.of("test-provider@1"));var active=RecoveryEngine.evaluate(initial.state(),initial.profile(),null,rules,resume);var bad=request(UUID.randomUUID(),Command.EXTERNAL,NOW,0,0,ZERO,false,active.state().current().id(),"first",11,Set.of("test-provider@1"));assertThrows(IllegalArgumentException.class,()->RecoveryEngine.evaluate(active.state(),active.profile(),null,rules,bad));}
 @Test void waitingUsesPersistedTimestampsAndClockRegressionIsRejected(){var rules=rules(RecoveryRules.Type.WAIT_PERIOD);var started=RecoveryEngine.evaluate(null,profile(-101),null,rules,request(Command.START,NOW));var next=RecoveryEngine.evaluate(started.state(),started.profile(),null,rules,request(Command.READ,NOW.plusSeconds(10)));assertEquals(5,next.profile().systemScore());assertThrows(IllegalStateException.class,()->RecoveryEngine.evaluate(next.state(),next.profile(),null,rules,request(Command.READ,NOW.minusSeconds(1))));}
 @Test void confirmedSignalPausesButOrdinaryNegativeReputationDoesNot()throws Exception{var rules=rules(RecoveryRules.Type.ACTIVE_PLAYTIME);var p=ProtectionFixtures.defaults(directory);var trust=TrustModel.initial(PLAYER,"global",new org.dextur.reputation.domain.VoterFacts(true,true,108000,NOW.minusSeconds(604800),true,true,true),p,NOW,0);var initial=RecoveryEngine.evaluate(null,profile(-100),trust,rules,request(Command.START,NOW));var confirmed=new ProtectionData.Trust(trust.player(),trust.scope(),trust.score(),1,trust.calculatedAt(),trust.revision(),trust.inputRevision(),trust.playtimeSeconds(),trust.firstJoined(),trust.factsAt(),trust.submitted(),trust.invalidated(),1,NOW.plusSeconds(60),trust.explanation());var next=RecoveryEngine.evaluate(initial.state(),profile(-10000),confirmed,rules,request(Command.READ,NOW.plusSeconds(1)));assertEquals(RecoverySnapshot.Status.PAUSED,next.snapshot().status());assertEquals(initial.state().current().id(),next.state().current().id());assertThrows(IllegalArgumentException.class,()->TrustModel.rehabilitate(confirmed,1000,NOW.plusSeconds(1)));}
 @Test void creditCapAndReproductionDoNotEraseConfirmedPenalty()throws Exception{var rules=ProtectionFixtures.defaults(directory);var facts=new org.dextur.reputation.domain.VoterFacts(true,true,108000,NOW.minusSeconds(604800),true,true,true);var trust=TrustModel.initial(PLAYER,"global",facts,rules,NOW,0);assertThrows(IllegalArgumentException.class,()->TrustModel.rehabilitate(trust,100001,NOW));var credited=TrustModel.rehabilitate(trust,10000,NOW);assertEquals(510000,TrustModel.reproduce(credited));var confirmed=new ProtectionData.Trust(credited.player(),credited.scope(),credited.score(),1,credited.calculatedAt(),credited.revision(),credited.inputRevision(),credited.playtimeSeconds(),credited.firstJoined(),credited.factsAt(),credited.submitted(),credited.invalidated(),1,NOW.plusSeconds(60),credited.explanation());var recalculated=TrustModel.calculate(PLAYER,"global",facts,rules,NOW.plusSeconds(1),confirmed,1,List.of(),false);assertFalse(recalculated.explanation().containsKey("rehabilitation_credit"));assertEquals(TrustModel.reproduce(recalculated),recalculated.score());}
 @Test void loginTimezoneUsesCalendarBoundaryAcrossDst(){var stage=new RecoveryRules.Stage("days",text("days"),"BOOK",List.of(objective("days",RecoveryRules.Type.LOGIN_DAYS,2)),5,0);var rules=program(List.of(stage),5,10);Instant begin=Instant.parse("2027-03-28T00:29:58Z");var first=RecoveryEngine.evaluate(null,profile(-101),null,rules,request(Command.START,begin));var logged=RecoveryEngine.evaluate(first.state(),first.profile(),null,rules,sample(begin,0,0));var day=RecoveryEngine.evaluate(logged.state(),logged.profile(),null,rules,sample(begin.plusSeconds(2),2,2));assertEquals(1,day.state().loginDays().size());var before=RecoveryEngine.evaluate(day.state(),day.profile(),null,rules,sample(Instant.parse("2027-03-28T21:59:59Z"),4,4));assertEquals(1,before.state().loginDays().size());var next=RecoveryEngine.evaluate(before.state(),before.profile(),null,rules,request(UUID.randomUUID(),Command.SAMPLE,Instant.parse("2027-03-28T22:00:00Z"),0,0,UUID.randomUUID(),true,ZERO,"",0,Set.of()));var done=RecoveryEngine.evaluate(next.state(),next.profile(),null,rules,request(UUID.randomUUID(),Command.SAMPLE,Instant.parse("2027-03-28T22:00:02Z"),2,2,next.state().session(),false,ZERO,"",0,Set.of()));assertEquals(RecoverySnapshot.Status.COMPLETED,done.snapshot().status());assertEquals(List.of("2027-03-28","2027-03-29"),done.state().loginDays());}
 @Test void lifetimeCapSurvivesRepeatedProgramsAndCannotBeRefunded(){var rules=rules(RecoveryRules.Type.WAIT_PERIOD);org.dextur.reputation.domain.recovery.RecoveryData.State state=null;var profile=profile(-201);Instant at=NOW;for(int program=0;program<3;program++){var start=RecoveryEngine.evaluate(state,profile,null,rules,request(Command.START,at));var first=RecoveryEngine.evaluate(start.state(),start.profile(),null,rules,request(Command.READ,at.plusSeconds(10)));var done=RecoveryEngine.evaluate(first.state(),first.profile(),null,rules,request(Command.READ,at.plusSeconds(20)));assertEquals(RecoverySnapshot.Status.COMPLETED,done.snapshot().status());state=done.state();profile=done.profile();assertEquals(program==0?12:20,profile.systemScore());at=at.plusSeconds(2592021);}assertEquals(6,state.rewards().size());assertEquals(3,state.enrollments().size());assertEquals(20,state.lifetimeReward());assertEquals(0,state.rewards().getLast().reputation());}
 @Test void cumulativeSamplesNeverReplayPreEnrollmentOrPausedActivity(){var rules=rules(RecoveryRules.Type.ACTIVE_PLAYTIME);var before=RecoveryEngine.evaluate(null,profile(-101),null,rules,sample(NOW,0,0));var started=RecoveryEngine.evaluate(before.state(),before.profile(),null,rules,request(Command.START,NOW.plusSeconds(5)));var boundary=RecoveryEngine.evaluate(started.state(),started.profile(),null,rules,sample(NOW.plusSeconds(10),10,10));assertEquals(0,boundary.state().active());var earned=RecoveryEngine.evaluate(boundary.state(),boundary.profile(),null,rules,sample(NOW.plusSeconds(14),14,14));assertEquals(4,earned.state().active());var paused=RecoveryEngine.evaluate(earned.state(),earned.profile(),null,rules,request(Command.PAUSE,NOW.plusSeconds(14)));var resumed=RecoveryEngine.evaluate(paused.state(),paused.profile(),null,rules,request(Command.RESUME,NOW.plusSeconds(24)));var reset=RecoveryEngine.evaluate(resumed.state(),resumed.profile(),null,rules,sample(NOW.plusSeconds(30),30,30));assertEquals(4,reset.state().active());assertTrue(reset.state().rewards().isEmpty());var done=RecoveryEngine.evaluate(reset.state(),reset.profile(),null,rules,sample(NOW.plusSeconds(36),36,36));assertEquals(5,done.profile().systemScore());}

 @Test void recomputedChecksumCannotHideInvalidProgressOrCompletion(){var rules=rules(RecoveryRules.Type.ACTIVE_PLAYTIME);var start=RecoveryEngine.evaluate(null,profile(-101),null,rules,request(Command.START,NOW));var text=ProtectionCodec.encode(start.state());var withProgress=text.replace("\"progress\":{\"first\":0}","\"progress\":{\"first\":11}");assertNotEquals(text,withProgress);assertThrows(RuntimeException.class,()->ProtectionCodec.decode(withProgress,org.dextur.reputation.domain.recovery.RecoveryData.State.class));var completed=text.replace("\"status\":\"ACTIVE\"","\"status\":\"COMPLETED\"");assertThrows(RuntimeException.class,()->ProtectionCodec.decode(completed,org.dextur.reputation.domain.recovery.RecoveryData.State.class));}

 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.EnumSource(RecoveryRules.Action.class)
 void everyConfirmedPolicyPreservesAuditAndNeverRestoresTrustPenalty(RecoveryRules.Action action)throws Exception{java.nio.file.Files.writeString(directory.resolve("recovery.yml"),"config-version: 1\nrecovery:\n  violations:\n    confirmed-abuse: "+action+"\n    administrative-lock: "+action+"\n");var recovery=org.dextur.reputation.application.RecoveryConfiguration.load(directory);var protection=ProtectionFixtures.defaults(directory);var facts=new org.dextur.reputation.domain.VoterFacts(true,true,108000,NOW.minusSeconds(604800),true,true,true);var trust=TrustModel.initial(PLAYER,"global",facts,protection,NOW,0);var start=RecoveryEngine.evaluate(null,profile(-101),trust,recovery,request(Command.START,NOW));var initial=RecoveryEngine.evaluate(start.state(),start.profile(),trust,recovery,sample(NOW,0,0));var partial=RecoveryEngine.evaluate(initial.state(),initial.profile(),trust,recovery,sample(NOW.plusSeconds(4),4,4));var marked=new ProtectionData.Trust(trust.player(),trust.scope(),trust.score(),1,trust.calculatedAt(),trust.revision(),trust.inputRevision(),trust.playtimeSeconds(),trust.firstJoined(),trust.factsAt(),trust.submitted(),trust.invalidated(),1,NOW.plusSeconds(60),trust.explanation());var confirmed=TrustModel.calculate(PLAYER,"global",facts,protection,NOW.plusSeconds(5),marked,1,List.of(),false);var decision=RecoveryEngine.evaluate(partial.state(),partial.profile(),confirmed,recovery,request(Command.READ,NOW.plusSeconds(5)));assertEquals(1,decision.state().confirmedSeen());var expected=action==RecoveryRules.Action.NONE?RecoverySnapshot.Status.ACTIVE:action==RecoveryRules.Action.CANCEL?RecoverySnapshot.Status.CANCELLED:RecoverySnapshot.Status.PAUSED;assertEquals(expected,decision.snapshot().status());assertEquals(0,decision.state().lifetimeTrust());assertEquals(confirmed.score(),decision.trust().score());if(action==RecoveryRules.Action.RESET_STAGE)assertTrue(decision.state().current().progress().isEmpty());else assertEquals(4,decision.state().current().progress().get("stabilization_active"));if(action!=RecoveryRules.Action.NONE)assertTrue(decision.events().stream().anyMatch(e->e.kind()==RecoveryService.Kind.PROGRAM_PAUSED||e.kind()==RecoveryService.Kind.PROGRAM_CANCELLED));else{var reward=RecoveryEngine.evaluate(decision.state(),decision.profile(),confirmed,recovery,sample(NOW.plusSeconds(18004),18004,18004));assertEquals(5,reward.profile().systemScore());assertEquals(0,reward.state().lifetimeTrust());assertEquals(confirmed.score(),reward.trust().score());}}

}
